import{_ as n,y as i,a as l,o as h,a2 as s,D as a,g as t,I as o}from"./chunks/framework.DCcmcJcL.js";const b=JSON.parse('{"title":"Data Transfer","description":"","frontmatter":{},"headers":[],"relativePath":"settings/data-transfer.md","filePath":"settings/data-transfer.md","lastUpdated":1789330126000}'),p={name:"settings/data-transfer.md"};function g(d,e,m,c,u,f){const r=i("ImagePopup");return h(),l("div",null,[e[0]||(e[0]=s('<h1 id="data-transfer" tabindex="-1">Data Transfer <a class="header-anchor" href="#data-transfer" aria-label="Permalink to &quot;Data Transfer&quot;">​</a></h1><p>Data transfer imports products, customers and tax rates in bulk from a spreadsheet, so a large catalog does not have to be typed in one record at a time.</p><p>From Bagisto 2.4.9, saving an import runs it through to the end on its own. Validation, image fetching, record creation, linking and indexing follow one another automatically, and a stepper at the top of the page shows the live progress of each phase.</p><h2 id="creating-an-import" tabindex="-1">Creating an import <a class="header-anchor" href="#creating-an-import" aria-label="Permalink to &quot;Creating an import&quot;">​</a></h2><ol><li>Go to <strong>Settings &gt;&gt; Data Transfer &gt;&gt; Imports</strong>.</li><li>Click <strong>Create Import</strong>.</li></ol>',5)),a(r,{src:"/images/settings/import.png",alt:"Imports listing with the Create Import button"}),e[1]||(e[1]=s('<ol start="3"><li>Choose the <strong>Type</strong> of records to import: products, customers or tax rates.</li><li>Click <strong>Download Sample</strong> to get a file in the expected layout, and prepare your own file to match it.</li><li>Choose the <strong>File</strong> (CSV, XLS, XLSX or XML).</li><li>For products, choose where the <strong>Product Images</strong> named in the file are found; the options are described below.</li><li>Choose the <strong>Action</strong>: create or update the records, or delete them.</li><li>Set the remaining fields described below.</li><li>Click <strong>Import</strong> and confirm the message <em>The import will start as soon as this is saved. Do you want to continue?</em></li></ol>',1)),a(r,{src:"/images/settings/create-import.png",alt:"Create Import form"}),e[2]||(e[2]=s('<p>Simple, configurable, virtual, bundle and grouped products can be imported; downloadable products cannot.</p><h3 id="the-remaining-fields" tabindex="-1">The remaining fields <a class="header-anchor" href="#the-remaining-fields" aria-label="Permalink to &quot;The remaining fields&quot;">​</a></h3><p><strong>Validation Strategy:</strong> <strong>Skip Errors</strong> imports the valid rows and leaves the faulty ones out; <strong>Stop on Errors</strong> halts the import after validation if any row is invalid.</p><p><strong>Allowed Errors:</strong> With <strong>Skip Errors</strong>, the number of faulty rows the import tolerates before it stops anyway.</p><p><strong>Field Separator:</strong> The character that separates columns in a CSV file, usually a comma.</p><p><strong>Process In Queue:</strong> Runs the import in the background. Validation and image downloading are spread across the store&#39;s queue workers, so a large file is not processed in one request. Your store needs a queue worker for this; if it is not set up to run jobs in the background, Bagisto asks you to change that before the import can start. With the switch off, the import runs in short browser-driven windows instead, so no single request runs long enough to time out; closing the page pauses the run at the phase it had reached, and reopening the import picks it up from there.</p><h3 id="product-images" tabindex="-1">Product images <a class="header-anchor" href="#product-images" aria-label="Permalink to &quot;Product images&quot;">​</a></h3><p>The images named in a product file can come from three places. Pick the one that matches your file; the choice is checked during validation, and a mismatch is reported as an error rather than importing every product without its images.</p><ul><li><strong>Image links in the file</strong> (recommended): put the full <code>https://</code> address of each image in the <strong>images</strong> column. Every link is fetched once, in a phase of its own, before any row is written, so nothing has to be placed on the server first.</li><li><strong>Upload a ZIP of images</strong>: upload a single archive containing every image, and name the files inside it in the <strong>images</strong> column. <strong>Download sample images</strong> gives you an archive that matches the sample sheet. When you reopen an import that already has an archive, the page shows its name and how many images are ready; choosing a new archive replaces them.</li><li><strong>Images already on the server</strong>: if someone can place files on the server, put the images in a folder under the store&#39;s import directory and enter that folder&#39;s name in <strong>Images Directory Path</strong>. The field&#39;s hint shows the exact location.</li></ul><p>The method you pick is saved on the import, so reopening it restores the choice along with the value that went with it.</p>',10)),a(r,{src:"/images/settings/import-image-source.png",alt:"Product Images source options"}),e[3]||(e[3]=s('<h2 id="following-the-import" tabindex="-1">Following the import <a class="header-anchor" href="#following-the-import" aria-label="Permalink to &quot;Following the import&quot;">​</a></h2><p>Once saved, the import runs on its own and the stepper shows which phase it is in:</p><ul><li><strong>Validate</strong> – the file is read and checked row by row, with a progress bar.</li><li><strong>Images</strong> – every image link is fetched before any record is written. This phase appears only for <strong>Image links in the file</strong>; an archive or a server folder is read while the rows are written.</li><li><strong>Create / Delete</strong> – the records are written, or removed when the action is <strong>Delete</strong>.</li><li><strong>Link</strong> – relationships between the imported rows are resolved: configurable variants, grouped product associations, bundle options, booking data, and the related, cross-sell and up-sell links.</li><li><strong>Index</strong> – price, inventory and search data are rebuilt.</li></ul><p>A delete run has no images to fetch and nothing to link, so those phases are not shown for it.</p>',4)),a(r,{src:"/images/settings/import-stepper.png",alt:"Import stepper showing the phases"}),e[4]||(e[4]=t("p",null,[o("If the file has errors, the run stops after validation and shows the total rows processed, the invalid rows and the error count, with a "),t("strong",null,"Download Full Report"),o(" button for the complete list. With "),t("strong",null,"Skip Errors"),o(", the import can still proceed and the faulty rows are left out.")],-1)),e[5]||(e[5]=t("p",null,"When every phase is complete, the summary confirms the result. If any batch does not complete, the import finishes the batches it can and reports how many did not, so you can check the error report and run the import again for those rows.",-1)),a(r,{src:"/images/settings/import-done.png",alt:"Import summary after completion"}),e[6]||(e[6]=t("p",null,[o("The imported records are listed under the matching menu, for example "),t("strong",null,"Catalog >> Products"),o(".")],-1)),a(r,{src:"/images/settings/import-output.png",alt:"Imported products in the catalog"}),e[7]||(e[7]=t("h3",{id:"coming-back-to-a-running-import",tabindex:"-1"},[o("Coming back to a running import "),t("a",{class:"header-anchor",href:"#coming-back-to-a-running-import","aria-label":'Permalink to "Coming back to a running import"'},"​")],-1)),e[8]||(e[8]=t("p",null,[o("You do not have to watch an import finish. Leave the page, and the row under "),t("strong",null,"Settings >> Data Transfer >> Imports"),o(" carries a "),t("strong",null,"View Progress"),o(" action for as long as the run is going; it opens the same stepper at the phase the import has reached. Once the run is finished, the action reads "),t("strong",null,"Import"),o(" again, so the listing tells you at a glance whether anything is still in flight.")],-1))])}const y=n(p,[["render",g]]);export{b as __pageData,y as default};
